function logSoftmax(z) { const m = Math.max(...z); const lse = m + Math.log(z.reduce((s, v) => s + Math.exp(v - m), 0)); return z.map((v) => v - lse); }

const vocab = ["ডেলিভারি", "চার্জ", "কত", "টাকা"];
