    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>প্রোডাক্ট টিম জিজ্ঞাসা করছে: “চ্যাটবটের উত্তর কম পুনরাবৃত্তিমূলক কিন্তু নিরাপদ রাখতে কোন সেটিং দেব?” মতামত নয়, সংখ্যা চাই—প্রতিটি সেটিং-এ আউটপুট কতটা বৈচিত্র্যময়, কতবার অদ্ভুত token আসে, এবং একই seed-এ ফল পুনরুৎপাদন হয় কিনা।</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>temperature, top-k, top-p ও seed একত্রে একটি decode pipeline-এ প্রয়োগ করতে পারবেন</li><li>sampling সেটিং-এর প্রভাব বণ্টন, গণনা ও বৈচিত্র্যে মাপতে পারবেন</li><li>reference ক্রমের cross-entropy হিসাব করে মডেলের “বিস্ময়” ব্যাখ্যা করতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 60 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/hallucination-calibration/">Hallucination, Calibration ও মূল্যায়ন</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>খেলনা মডেল:</strong> LOGITS[প্রসঙ্গ][token] = স্কোর। প্রসঙ্গ শুধু আগের একটি শব্দ (bigram-এর মতো), যাতে টেবিল পড়া যায়। “&lt;eos&gt;” পেলে বা ৮ token পরে থামে।</p><p><strong>Pipeline:</strong> logit → temperature (T = ০ হলে greedy) → softmax → top-k → top-p → renormalize → seed-যুক্ত sample। প্রতিটি ধাপ পাঠ ৯.২–৯.৩-এর ফাংশন।</p><div class="wgba-table-wrap"><table><caption>playground-এর মাপ</caption><thead><tr><th scope="col">মাপ</th><th scope="col">অর্থ</th></tr></thead><tbody><tr><td>অনন্য বাক্য</td><td>২০টি নমুনায় কতগুলো আলাদা—বৈচিত্র্য</td></tr><tr><td>বিরল token-এর হার</td><td>মূল বণ্টনে p < ০.০৫ এমন token কতবার এল—“অদ্ভুত” আউটপুটের প্রক্সি</td></tr><tr><td>reference cross-entropy</td><td>একটি প্রত্যাশিত বাক্যের প্রতি-token গড় −log p—মডেলের “বিস্ময়”</td></tr></tbody></table></div><div class="wgba-note">logit টেবিল হাতে লেখা খেলনা মডেল; সংখ্যাগুলো কোনো আসল LLM-এর আচরণ বোঝায় না। পদ্ধতিটি (একই seed-সেটে সেটিং তুলনা, বৈচিত্র্য ও বিরল-token মাপ) বাস্তব মূল্যায়নেও ব্যবহারযোগ্য।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> Playground হলো সাউন্ড মিক্সারের সামনে বসে প্রতিটি নব আলাদাভাবে ঘুরিয়ে মিটারে দেখা—শুধু কানে নয়, সংখ্যায়।</p><p><strong>কোথায় ভাঙে:</strong> মিক্সারের নব স্বাধীন; এখানে temperature top-p-এর সেট-আকারও বদলায়—নবগুলো পরস্পরের ওপর প্রভাব ফেলে।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>প্রসঙ্গ “চার্জ”-এর logit: কত = ৩, ফ্রি = ১.৫, আছে = ১, ভাই = −১।</p><ol><li>T = ১: e-ঘাত [২০.০৯, ৪.৪৮, ২.৭২, ০.৩৭], যোগ ২৭.৬৬; softmax ≈ [০.৭২৬, ০.১৬২, ০.০৯৮, ০.০১৩]। “ভাই” বিরল (< ০.০৫)।</li><li>top-p ০.৯: ০.৭২৬ + ০.১৬২ = ০.৮৮৮ < ০.৯; + ০.০৯৮ = ০.৯৮৭ → ৩টি রাখা, “ভাই” বাদ।</li><li>renormalize: ÷ ০.৯৮৭ ≈ [০.৭৩৬, ০.১৬৪, ০.১০০, ০]।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><p><strong>প্রজেক্ট মানদণ্ড:</strong> (১) “চার্জ” প্রসঙ্গে চারটি রূপান্তরের বণ্টন টেবিল, (২) ১০০০ নমুনার গণনা প্রত্যাশার সাথে, (৩) পাঁচটি সেটিং-এর অনন্য বাক্য ও বিরল-token সংখ্যা (২০০টি seed), (৪) একই seed-এ পুনরুৎপাদন প্রমাণ, (৫) আপনার সুপারিশকৃত সেটিং ও তার যুক্তি—সীমাসহ।</p><h3>প্রজেক্ট: sampling playground (খেলনা মডেল)</h3><div class="wgba-playground-slot" data-exercise="ex-les-09-06-project-sampling-playground-1"><pre class="wgba-code"><code>function makeRng(seed) {
  let a = seed &gt;&gt;&gt; 0;
  return function () {
    a = (a + 0x6D2B79F5) &gt;&gt;&gt; 0;
    let t = a;
    t = Math.imul(t ^ (t &gt;&gt;&gt; 15), t | 1);
    t ^= t + Math.imul(t ^ (t &gt;&gt;&gt; 7), t | 61);
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}
const r3 = (x) =&gt; Math.round(x * 1000) / 1000;
function softmax(z) { const m = Math.max(...z); const e = z.map((v) =&gt; Math.exp(v - m)); const s = e.reduce((a, b) =&gt; a + b, 0); return e.map((v) =&gt; v / s); }

// খেলনা মডেল: আগের শব্দ → পরের token-এর logit (হাতে লেখা)
const LOGITS = {
  &quot;&lt;bos&gt;&quot;:    { &quot;ঢাকার&quot;: 2, &quot;ডেলিভারি&quot;: 1.5, &quot;আমার&quot;: 1.2, &quot;দাম&quot;: 0.5 },
  &quot;ঢাকার&quot;:    { &quot;বাইরে&quot;: 2.5, &quot;ভেতরে&quot;: 1, &quot;ডেলিভারি&quot;: 0.8 },
  &quot;বাইরে&quot;:    { &quot;ডেলিভারি&quot;: 2.5, &quot;চার্জ&quot;: 1 },
  &quot;ভেতরে&quot;:    { &quot;ডেলিভারি&quot;: 2.5, &quot;চার্জ&quot;: 1 },
  &quot;ডেলিভারি&quot;: { &quot;চার্জ&quot;: 2.5, &quot;কবে&quot;: 1.5, &quot;হবে&quot;: 0.5 },
  &quot;চার্জ&quot;:    { &quot;কত&quot;: 3, &quot;ফ্রি&quot;: 1.5, &quot;আছে&quot;: 1, &quot;ভাই&quot;: -1 },
  &quot;আমার&quot;:     { &quot;অর্ডার&quot;: 2.5, &quot;পার্সেল&quot;: 1.5 },
  &quot;অর্ডার&quot;:   { &quot;কোথায়&quot;: 2, &quot;কবে&quot;: 1.5 },
  &quot;পার্সেল&quot;:  { &quot;কোথায়&quot;: 2, &quot;কবে&quot;: 1.5 },
  &quot;দাম&quot;:      { &quot;কত&quot;: 3, &quot;কম&quot;: 1 },
  &quot;কত&quot;:       { &quot;&lt;eos&gt;&quot;: 2, &quot;টাকা&quot;: 1.5, &quot;দিন&quot;: 0.5 },
  &quot;কবে&quot;:      { &quot;আসবে&quot;: 2, &quot;&lt;eos&gt;&quot;: 1, &quot;হবে&quot;: 0.5 },
  &quot;টাকা&quot;: { &quot;&lt;eos&gt;&quot;: 3 }, &quot;দিন&quot;: { &quot;&lt;eos&gt;&quot;: 3 }, &quot;আসবে&quot;: { &quot;&lt;eos&gt;&quot;: 3 }, &quot;হবে&quot;: { &quot;&lt;eos&gt;&quot;: 3 }, &quot;ফ্রি&quot;: { &quot;&lt;eos&gt;&quot;: 2, &quot;কি&quot;: 1 }, &quot;কি&quot;: { &quot;&lt;eos&gt;&quot;: 3 },
  &quot;আছে&quot;: { &quot;&lt;eos&gt;&quot;: 2, &quot;কি&quot;: 1.5 }, &quot;কোথায়&quot;: { &quot;&lt;eos&gt;&quot;: 2, &quot;আছে&quot;: 1 }, &quot;কম&quot;: { &quot;&lt;eos&gt;&quot;: 2 }, &quot;ভাই&quot;: { &quot;&lt;eos&gt;&quot;: 2 },
};
const order = (p) =&gt; p.map((v, i) =&gt; [v, i]).sort((a, b) =&gt; b[0] - a[0] || a[1] - b[1]);
const renorm = (p) =&gt; { const s = p.reduce((a, b) =&gt; a + b, 0); return p.map((v) =&gt; v / s); };
function transform(z, { T = 1, k = Infinity, top = 1 }) {
  let p = T === 0 ? z.map((_, i) =&gt; (i === z.indexOf(Math.max(...z)) ? 1 : 0)) : softmax(z.map((v) =&gt; v / T));
  const steps = { temp: p };
  if (k &lt; p.length) { const keep = new Set(order(p).slice(0, k).map(([, i]) =&gt; i)); p = renorm(p.map((v, i) =&gt; (keep.has(i) ? v : 0))); }
  steps.topk = p;
  if (top &lt; 1) { const keep = new Set(); let c = 0; for (const [v, i] of order(p)) { keep.add(i); c += v; if (c &gt;= top - 1e-12) break; } p = renorm(p.map((v, i) =&gt; (keep.has(i) ? v : 0))); }
  steps.topp = p;
  return { p, steps };
}
function sampleIdx(p, rand) { const u = rand(); let c = 0; for (let i = 0; i &lt; p.length; i++) { c += p[i]; if (u &lt; c) return i; } return p.length - 1; }
function decode(settings, seed, maxLen = 8) {
  const rand = makeRng(seed), out = []; let prev = &quot;&lt;bos&gt;&quot;, rare = 0;
  for (let t = 0; t &lt; maxLen; t++) {
    const toks = Object.keys(LOGITS[prev]), z = toks.map((w) =&gt; LOGITS[prev][w]);
    const base = softmax(z), { p } = transform(z, settings);
    const i = sampleIdx(p, rand);
    if (base[i] &lt; 0.05) rare++;
    if (toks[i] === &quot;&lt;eos&gt;&quot;) break;
    out.push(toks[i]); prev = toks[i];
  }
  return { text: out.join(&quot; &quot;), rare, len: out.length };
}

// ১) একটি প্রসঙ্গে রূপান্তর
const toks = Object.keys(LOGITS[&quot;চার্জ&quot;]), z = toks.map((w) =&gt; LOGITS[&quot;চার্জ&quot;][w]);
const tr = transform(z, { T: 1, top: 0.9 });
console.log(&quot;প্রসঙ্গ «চার্জ» token:&quot;, toks.join(&quot;, &quot;));
console.log(&quot;  T=1        :&quot;, JSON.stringify(tr.steps.temp.map(r3)));
console.log(&quot;  + top-p 0.9:&quot;, JSON.stringify(tr.steps.topp.map(r3)));
console.log(&quot;  T=0        :&quot;, JSON.stringify(transform(z, { T: 0 }).p));

// ২) 1000 নমুনা
const rand = makeRng(1), cnt = toks.map(() =&gt; 0);
